func (this *Control) Internal_new_GC(data *GCData) int64 {
	this.CheckWidget()
	var gdkResource int64
	if gtk.GTKGTK4 {
		gdkResource = this.impl.paintSurface_()
	} else {
		gdkResource = this.impl.paintWindow_()
	}
	if gdkResource == 0 {
		this.Error(ERROR_NO_HANDLES)
	}
	var gc int64 = data.Cairo
	if gc != 0 {
		gtk.CairoCairo_reference(gc)
	} else {
		if gtk.GTKGTK4 {
			var surface int64 = gtk.GDKGdk_surface_create_similar_surface(gdkResource, gtk.CairoCAIRO_CONTENT_COLOR_ALPHA, data.Width, data.Height)
			gc = gtk.CairoCairo_create(surface)
		} else {
			gc = gtk.GDKGdk_cairo_create(gdkResource)
		}
	}
	if gc == 0 {
		this.Error(ERROR_NO_HANDLES)
	}
	if data != (nil) {
		var mask int32 = LEFT_TO_RIGHT | RIGHT_TO_LEFT
		if (data.Style & mask) == 0 {
			data.Style |= this.style & (mask | MIRRORED)
		} else {
			if (data.Style & RIGHT_TO_LEFT) != 0 {
				data.Style |= MIRRORED
			}
		}
		data.Drawable = gdkResource
		data.Device = upcastDisplayToDevice(this.display)
		var control *Control = this.impl.findBackgroundControl_()
		if control == (nil) {
			control = this
		}
		if this.font != (nil) {
			data.Font = this.font
		} else {
			data.Font = this.impl.defaultFont_()
		}
		data.ForegroundRGBA = this.GetForegroundGdkRGBA()
		data.BackgroundRGBA = control.GetBackgroundGdkRGBA()
	}
	return gc
}

