func (this *Control) IsFocusAncestor(controlLike ControlLike) bool {
	var control *Control
	if controlLike != nil {
		control = controlLike.AsControl()
	}
	_ = control
	for control != (nil) && control != this && func() bool { _, ok103 := isControlToShell(control); return !(ok103) }() {
		control = upcastCompositeToControl(control.parent)
	}
	return control == this
}

// j2go: instanceof helper for Shell and its subclasses within the translated set.
func widgetImplAsShell(x any) (*Shell, bool) {
	if h, ok := x.(*widgetHooked); ok {
		x = h.hook
	}
	switch v := x.(type) {
	case *Shell:
		if v == nil {
			return nil, false
		}
		return v, true
	}
	if l, ok := x.(interface{ AsShell() *Shell }); ok {
		return l.AsShell(), true
	}
	return nil, false
}

func isControlToShell(x *Control) (*Shell, bool) {
	if x == nil {
		return nil, false
	}
	return widgetImplAsShell(x.impl)
}

