func ControlMagnifyProc(gesture int64, zoom float64, user_data int64) {
	if gtk.GTKGtk_gesture_is_recognized(gesture) {
		var state []int32 = make([]int32, 1)
		var x []float64 = make([]float64, 1)
		var y []float64 = make([]float64, 1)
		gtk.GTK3Gtk_get_current_event_state(state)
		gtk.GTKGtk_gesture_get_point(gesture, gtk.GTKGtk_gesture_get_last_updated_sequence(gesture), x, y)
		var delta float64 = gtk.GTKGtk_gesture_zoom_get_scale_delta(gesture)
		var control *Control = ControlGetControl(user_data)
		control.SendGestureEvent(state[0], GESTURE_MAGNIFY, int32(x[0]), int32(y[0]), delta)
	}
}

